let lang = 'zh'
function save(v) {
try { v ? root.localStorage.setItem(LK, v) : root.localStorage.removeItem(LK) } catch (e) {}
}
function fromUrl() {
try {
const m = /[?&]lang=(zh|en)(?:&|$)/.exec(root.location.search || '')
if (!m) return ''
save(m[1])
try {
const u = new URL(root.location.href)
u.searchParams.delete('lang')
root.history.replaceState(null, '', u.href)
} catch (e) {}
return m[1]
} catch (e) { return '' }
}
function detect() {
const u = fromUrl()
if (u) return u
let s = ''
try { s = root.localStorage.getItem(LK) || '' } catch (e) {}
if (s === 'zh' || s === 'en') return s
try { s = root.navigator.language || '' } catch (e) {}
return /^zh/i.test(s) ? 'zh' : 'en'
}
function t(key, vars) {
const i = KEYS.indexOf(key)
let s = i < 0 ? '' : (lang === 'en' ? EN[i] : ZH[i]) || ZH[i]
if (!s) return key
if (vars && typeof vars === 'object') s = s.replace(/\{(\w+)\}/g, (a, n) => (n in vars ? String(vars[n]) : a))
return s
}
function apply(scope) {
const doc = root.document
const host = scope || doc
if (!host || !host.querySelectorAll) return
host.querySelectorAll('[data-i18n]').forEach((el) => { el.textContent = t(el.getAttribute('data-i18n')) })
host.querySelectorAll('[data-i18n-attr]').forEach((el) => el.getAttribute('data-i18n-attr').split(',').forEach((p) => {
const i = p.indexOf(':')
if (i > 0) el.setAttribute(p.slice(0, i).trim(), t(p.slice(i + 1).trim()))
}))
host.querySelectorAll('[data-i18n-title]').forEach((el) => { el.setAttribute('title', t(el.getAttribute('data-i18n-title'))) })
if (!doc) return
if (doc.documentElement) doc.documentElement.setAttribute('lang', lang === 'zh' ? 'zh-CN' : 'en')
doc.title = t('app.title')
}
function init() { return (lang = detect()), apply(), lang }
function setLang(v) { return save(v === 'zh' || v === 'en' ? v : ''), init() }
